for (let i = 0; i < 80; i++) events.push({ status: 200, rejected: false });
for (let i = 0; i < 5; i++) events.push({ status: 500, rejected: false });
for (let i = 0; i < 15; i++) events.push({ status: 200, rejected: true });
const r = errorRate(events);
const ok = Math.abs(r - 0.20) < 1e-9;
console.log(ok ? 'PASS' : 'FAIL rate=' + r);

