function metrics(req, res, next) {
  const start = Date.now();
  res.on('finish', () => {
    const ms = Date.now() - start;
    metricsClient.gauge('latency_avg_ms', ms);          // average latency
    if (res.statusCode >= 500) metricsClient.inc('errors_5xx');
  });
  next();
}
// note: pool, breaker, and retry layers emit no metrics of their own
